import { usePanier } from "../../hooks/usePanier";

export default function LignePanier({ article }) {
  const { retirerDuPanier } = usePanier();

  return (
    <div>
      <p>{article.title}</p>
      <button onClick={() => retirerDuPanier(article.id)}>
        Supprimer
      </button>
    </div>
  );
}
